package dev.vrmc.provider;

import java.io.File;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.file.Files;
import java.security.MessageDigest;

/**
 * Cross-language C -> Java contract test for the M4-W1 input channel (design §7.2).
 *
 * <p>Consumes the artifacts produced by {@code bridge/tests/make_input_fixture.c}:
 * <ul>
 *   <li>{@code VRMC_INPUT_FIXTURE} = ONE raw 752-byte {@code vrmc_input_state} contract snapshot
 *       (C-generated bytes, parsed by the Java gesture engine);</li>
 *   <li>{@code VRMC_INPUT_FIXTURE_FRAMES} (default {@code $VRMC_INPUT_FIXTURE.frames}) = an optional
 *       10-record / 7520-byte timeline replayed with each record's own timestamp_ns.</li>
 * </ul>
 *
 * <p>Skip rules: unset primary env = clear SKIP (fixture not generated); SET but missing = visible
 * FAIL. The timeline is an explicit SKIP when absent, never a silent pass. Run by
 * provider/tests/run_tests.sh and scripts/m4_input_selfcheck.sh.
 */
public final class VisionInputFixtureTest {
    /** Contract sha256 of the primary 752-byte snapshot (bridge-input generator, 2026-11-01). */
    private static final String PRIMARY_SHA256 =
        "50926fdc3ffc640dcbdee440679f83aa4c28ccbcdf628ec0cbca6c05cf562d77";
    /** Contract sha256 of the 10-record / 7520-byte timeline sidecar. */
    private static final String FRAMES_SHA256 =
        "43d52113c5e925e2a59c48387a2fddb5b4427bf4342d0a2bbe83f8914f76fa45";

    private static final int RECORD_BYTES = VisionInput.INPUT_BYTES;
    private static final int PRIMARY_RECORDS = 10;
    private static final long MS = 1_000_000L;
    private static final long TIMELINE_START_NS = 1_000_000_000L;
    private static final long TIMELINE_STEP_NS = 150L * MS;

    private static int failures;
    private static int checks;
    private static int skipped;

    public static void main(String[] args) {
        System.out.println("[m4-fixture-test] C -> Java vrmc_input_state contract (cross-language)");
        String primaryPath = env("VRMC_INPUT_FIXTURE");
        if (primaryPath == null || primaryPath.isBlank()) {
            System.out.println("[m4-fixture-test] SKIP: VRMC_INPUT_FIXTURE unset - cross-language fixture "
                + "not generated (run bridge/tests/make_input_fixture.c, see scripts/m4_input_selfcheck.sh)");
            return;
        }
        File primaryFile = new File(primaryPath);
        if (!primaryFile.isFile()) {
            System.out.println("[m4-fixture-test] FAIL: VRMC_INPUT_FIXTURE is set but the file does not exist: "
                + primaryPath);
            System.exit(1);
            return;
        }
        byte[] primary = readBytes(primaryFile);
        if (primary == null) {
            System.exit(1);
            return;
        }
        try {
            primaryContractSnapshot(primaryFile, primary);
        } catch (Throwable t) {
            t.printStackTrace();
            failures++;
        }

        String framesEnv = env("VRMC_INPUT_FIXTURE_FRAMES");
        boolean framesExplicit = framesEnv != null && !framesEnv.isBlank();
        File framesFile = framesExplicit ? new File(framesEnv) : new File(primaryPath + ".frames");
        if (!framesFile.isFile()) {
            if (framesExplicit) {
                System.out.println("[m4-fixture-test] FAIL: VRMC_INPUT_FIXTURE_FRAMES is set but the file does "
                    + "not exist: " + framesFile);
                failures++;
            } else {
                skipped++;
                System.out.println("[m4-fixture-test] SKIP: timeline sidecar not found (" + framesFile
                    + ") - primary 752-byte contract test still ran");
            }
        } else {
            byte[] frames = readBytes(framesFile);
            if (frames != null) {
                try {
                    timelineReplay(framesFile, frames);
                } catch (Throwable t) {
                    t.printStackTrace();
                    failures++;
                }
            }
        }

        System.out.println();
        System.out.printf("[m4-fixture-test] %d checks, %d failed, %d skipped%n", checks, failures, skipped);
        System.out.println(failures == 0 ? "[m4-fixture-test] PASS" : "[m4-fixture-test] FAIL");
        System.exit(failures == 0 ? 0 : 1);
    }

    // ------------------------------------------------------------------------------------------
    // 1. primary 752-byte contract snapshot
    // ------------------------------------------------------------------------------------------
    private static void primaryContractSnapshot(File file, byte[] bytes) {
        section("primary contract snapshot (one raw vrmc_input_state)");
        System.out.println("[m4-fixture-test] primary=" + file.getAbsolutePath() + " bytes=" + bytes.length
            + " sha256=" + sha256(bytes));
        check("file is exactly one 752-byte vrmc_input_state (actual=" + bytes.length + ")", bytes.length == RECORD_BYTES);
        if (bytes.length != RECORD_BYTES) {
            return;
        }
        check("sha256 matches the documented C-generated contract image (actual=" + sha256(bytes) + ")",
            PRIMARY_SHA256.equals(sha256(bytes)));

        VisionInput in = new VisionInput();
        ByteBuffer buffer = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);
        boolean accepted = in.poll(buffer, 0, TIMELINE_START_NS);
        check("parser accepts the C image", accepted);
        checkEq("frame_index == 8", in.frameIndex(), 8);
        checkEq("valid_mask == 3", in.validMask(), 3);
        checkEq("timestamp_ns == 1960000000", in.snapshotTimestampNs(), 1960000000L);
        check("LEFT hand tracked", in.isHandTracked(VisionInput.HAND_LEFT));
        check("RIGHT hand tracked", in.isHandTracked(VisionInput.HAND_RIGHT));
        checkEq("hands[0] chirality == 0 (left)", in.chirality(VisionInput.HAND_LEFT), 0);
        checkEq("hands[1] chirality == 1 (right)", in.chirality(VisionInput.HAND_RIGHT), 1);
        check("hands are ordered LEFT then RIGHT (wrist x signs)", in.wristX(VisionInput.HAND_LEFT) < 0.0F
            && in.wristX(VisionInput.HAND_RIGHT) > 0.0F);

        // Documented metrics, strict thresholds (§5.3 defaults): right = pinch+fist, left = relaxed open.
        float rightPinch = in.pinchDistance(VisionInput.HAND_RIGHT);
        float rightFist = in.fistRatio(VisionInput.HAND_RIGHT);
        float leftPinch = in.pinchDistance(VisionInput.HAND_LEFT);
        float leftFist = in.fistRatio(VisionInput.HAND_LEFT);
        System.out.printf("[m4-fixture-test] metrics: R pinch=%.4f R fist=%.4f L pinch=%.4f L fist=%.4f%n",
            rightPinch, rightFist, leftPinch, leftFist);
        checkClose("RIGHT pinch distance ~= 0.0050 m", rightPinch, 0.0050F, 1.0E-3F);
        checkClose("RIGHT fist ratio ~= 0.9809", rightFist, 0.9809F, 1.0E-3F);
        checkClose("LEFT pinch distance ~= 0.0680 m", leftPinch, 0.0680F, 1.0E-3F);
        checkClose("LEFT fist ratio ~= 1.7900", leftFist, 1.7900F, 1.0E-3F);
        check("RIGHT pinch distance < pinchOn 0.030", rightPinch < in.pinchOn());
        check("RIGHT fist ratio < fistOn 1.25", rightFist < in.fistOn());
        check("LEFT pinch distance > pinchOff 0.045", leftPinch > in.pinchOff());
        check("LEFT fist ratio > fistOff 1.55", leftFist > in.fistOff());
        check("RIGHT raw pinch press detected", in.pinchRaw(VisionInput.HAND_RIGHT));
        check("RIGHT raw fist detected", in.fistRaw(VisionInput.HAND_RIGHT));
        check("LEFT raw pinch not detected", !in.pinchRaw(VisionInput.HAND_LEFT));
        check("LEFT raw fist not detected", !in.fistRaw(VisionInput.HAND_LEFT));
        // G4: a first frame that is already pinched/fisted must never present as a stuck press.
        check("SAFETY: no pressed pinch on the acquisition frame", !in.pinchPressed(VisionInput.HAND_RIGHT));
        check("SAFETY: no engaged fist press on the acquisition frame", !in.fistPressed(VisionInput.HAND_RIGHT));
        check("SAFETY: no fist-tap pulse on the acquisition frame", !in.fistTapPressed(VisionInput.HAND_RIGHT));
        check("no invalid hand data flagged", in.invalidHandMask() == 0);
        check("snapshot is healthy (not stale)", in.isInputHealthy() && !in.isStale());
    }

    // ------------------------------------------------------------------------------------------
    // 2. optional timeline sidecar (10 x 752 records, replayed on their own timestamps)
    // ------------------------------------------------------------------------------------------
    private static void timelineReplay(File file, byte[] bytes) {
        section("timeline replay (record timestamps, 150 ms documented spacing)");
        System.out.println("[m4-fixture-test] frames=" + file.getAbsolutePath() + " bytes=" + bytes.length
            + " sha256=" + sha256(bytes));
        check("timeline is exactly " + PRIMARY_RECORDS + " x 752 = " + (PRIMARY_RECORDS * RECORD_BYTES)
            + " bytes (actual=" + bytes.length + ")", bytes.length == PRIMARY_RECORDS * RECORD_BYTES);
        if (bytes.length != PRIMARY_RECORDS * RECORD_BYTES) {
            return;
        }
        check("timeline sha256 matches the documented C-generated image (actual=" + sha256(bytes) + ")",
            FRAMES_SHA256.equals(sha256(bytes)));

        ByteBuffer buffer = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);
        VisionInput in = new VisionInput();
        boolean[] rPinch = new boolean[PRIMARY_RECORDS];
        boolean[] lPinch = new boolean[PRIMARY_RECORDS];
        boolean[] rFist = new boolean[PRIMARY_RECORDS];
        boolean[] lFist = new boolean[PRIMARY_RECORDS];
        boolean[] rTap = new boolean[PRIMARY_RECORDS];
        boolean[] lTap = new boolean[PRIMARY_RECORDS];
        boolean[] bothTap = new boolean[PRIMARY_RECORDS];
        long[] ts = new long[PRIMARY_RECORDS];
        for (int i = 0; i < PRIMARY_RECORDS; i++) {
            long timestamp = buffer.getLong(i * RECORD_BYTES + VisionInput.INPUT_OFF_TIMESTAMP);
            ts[i] = timestamp;
            buffer.position(i * RECORD_BYTES);
            boolean accepted = in.poll(buffer, 0, timestamp);
            if (!accepted) {
                check("record " + i + " accepted", false);
                continue;
            }
            checkEq("record " + i + " valid_mask == 3", in.validMask(), 3);
            rPinch[i] = in.pinchPressed(VisionInput.HAND_RIGHT);
            lPinch[i] = in.pinchPressed(VisionInput.HAND_LEFT);
            rFist[i] = in.fistPressed(VisionInput.HAND_RIGHT);
            lFist[i] = in.fistPressed(VisionInput.HAND_LEFT);
            rTap[i] = in.fistTapPressed(VisionInput.HAND_RIGHT);
            lTap[i] = in.fistTapPressed(VisionInput.HAND_LEFT);
            bothTap[i] = in.bothFistTapPressed();
            System.out.printf("[m4-fixture-test] rec%d ts=%dms Rpinch=%-5s Lpinch=%-5s Rfist=%-5s Lfist=%-5s "
                    + "Ltap=%-5s%n", i, timestamp / MS, rPinch[i], lPinch[i], rFist[i], lFist[i], lTap[i]);
        }
        check("record 0 timestamp is the documented start (1000 ms)", ts[0] == TIMELINE_START_NS);
        boolean spacing = true;
        for (int i = 1; i < PRIMARY_RECORDS; i++) {
            if (ts[i] - ts[i - 1] != TIMELINE_STEP_NS) spacing = false;
        }
        check("record timestamps are 150 ms apart", spacing);

        // Documented expected gesture timeline (design §7.2 / bridge-input fixture contract):
        //   f0 open, f1 R pinch press, f2 held, f3 release, f4 L fist press, f5/f6 held,
        //   f7 450 ms hold -> one tap pulse, f8 same hold -> no repeat, f9 release.
        check("f0: open both (no gestures)", none(rPinch[0], lPinch[0], rFist[0], lFist[0]));
        check("f1: RIGHT pinch press", rPinch[1] && !lPinch[1] && !rFist[1] && !lFist[1]);
        check("f2: RIGHT pinch held", rPinch[2] && !lPinch[2]);
        check("f3: RIGHT pinch released", !rPinch[3] && !lPinch[3] && !rFist[3] && !lFist[3]);
        check("f4: LEFT fist press, left pinch stays released", lFist[4] && !rFist[4] && !lPinch[4] && !rPinch[4]);
        check("f5: LEFT fist held", lFist[5]);
        check("f6: LEFT fist held", lFist[6]);
        check("f7: LEFT fist held", lFist[7]);
        check("f8: LEFT fist still held", lFist[8]);
        check("f9: released", !lFist[9] && !rFist[9] && !lPinch[9] && !rPinch[9]);

        // Fist tap is data-driven: a tap is expected iff the continuous hold reached holdMs.
        long holdNs = ts[7] - ts[4];
        boolean tapExpected = holdNs >= in.fistHoldMillis() * MS;
        System.out.printf("[m4-fixture-test] left-fist continuous hold f4..f7 = %d ms (holdMs=%d) -> tap %s%n",
            holdNs / MS, in.fistHoldMillis(), tapExpected ? "expected" : "NOT expected");
        check("no tap before the hold threshold (f0..f6)", !any(lTap, 0, 7) && !any(rTap, 0, 7));
        check("fist-tap expected iff hold >= holdMs", countRising(lTap) == (tapExpected ? 1 : 0));
        if (tapExpected) {
            check("exactly one tap pulse at f7", lTap[7] && !lTap[6]);
            check("tap pulse is 2 frames (f7,f8)", lTap[7] && lTap[8] && !lTap[9]);
            check("no repeat pulse on the continuing hold (f8)", countRising(lTap) == 1);
        }
        check("right-hand fist tap never fires", !any(rTap, 0, PRIMARY_RECORDS));
        check("both-fist tap never fires (only one fist ever held)", !any(bothTap, 0, PRIMARY_RECORDS));
        check("every source released after f9", none(lPinch[9], rPinch[9], lFist[9], rFist[9], lTap[9]));
        check("no stuck gesture state after the timeline", !in.pinchPressed(VisionInput.HAND_LEFT)
            && !in.pinchPressed(VisionInput.HAND_RIGHT)
            && !in.fistPressed(VisionInput.HAND_LEFT)
            && !in.fistPressed(VisionInput.HAND_RIGHT)
            && !in.fistTapPressed(VisionInput.HAND_LEFT)
            && !in.fistTapPressed(VisionInput.HAND_RIGHT)
            && !in.bothFistTapPressed());
    }

    // ------------------------------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------------------------------
    private static String env(String name) {
        try {
            return System.getenv(name);
        } catch (SecurityException e) {
            return null;
        }
    }

    private static byte[] readBytes(File file) {
        try {
            return Files.readAllBytes(file.toPath());
        } catch (IOException e) {
            System.out.println("[m4-fixture-test] FAIL: cannot read " + file + ": " + e);
            failures++;
            return null;
        }
    }

    private static String sha256(byte[] bytes) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(bytes);
            StringBuilder sb = new StringBuilder(hash.length * 2);
            for (byte b : hash) {
                sb.append(Character.forDigit((b >> 4) & 0xF, 16));
                sb.append(Character.forDigit(b & 0xF, 16));
            }
            return sb.toString();
        } catch (Exception e) {
            return "sha256-error:" + e;
        }
    }

    private static boolean none(boolean... values) {
        for (boolean v : values) if (v) return false;
        return true;
    }

    private static boolean any(boolean[] values, int from, int toExclusive) {
        for (int i = from; i < toExclusive; i++) if (values[i]) return true;
        return false;
    }

    private static int countRising(boolean[] values) {
        int rising = 0;
        boolean prev = false;
        for (boolean v : values) {
            if (v && !prev) rising++;
            prev = v;
        }
        return rising;
    }

    private static void section(String name) {
        System.out.println();
        System.out.println("== " + name + " ==");
    }

    private static void check(String label, boolean ok) {
        checks++;
        if (!ok) failures++;
        System.out.printf("  %-86s %s%n", label, ok ? "ok" : "FAIL");
    }

    private static void checkEq(String label, int actual, int expected) {
        check(label + " (actual=" + actual + ")", actual == expected);
    }

    private static void checkEq(String label, long actual, long expected) {
        check(label + " (actual=" + actual + ")", actual == expected);
    }

    private static void checkClose(String label, float actual, float expected, float epsilon) {
        check(label + " (actual=" + actual + ")", Float.isFinite(actual) && Math.abs(actual - expected) <= epsilon);
    }
}
